fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let track: i32 = w * 8;
    let lx: i32 = w * 2 / 3;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 4 {
            host::display::state_set(8 + i * 2, i * 400);
            host::display::state_set(9 + i * 2, 12);
            i = i + 1;
        }
    }
    let red: bool = t % 360 >= 180;
    let mut x = [0; 4];
    let mut v = [0; 4];
    let mut i: i32 = 0;
    while i < 4 {
        x[i] = host::display::state_get(8 + i * 2);
        v[i] = host::display::state_get(9 + i * 2);
        i = i + 1;
    }
    i = 0;
    while i < 4 {
        let a: i32 = (i + 1) % 4;
        let mut gap: i32 = x[a] - x[i];
        if gap < 0 { gap = gap + track; }
        gap = gap - 240;
        if gap < 0 { gap = 0; }
        v[i] = v[i] + 1;
        if v[i] > 18 { v[i] = 18; }
        if v[i] > gap / 24 { v[i] = gap / 24; }
        if red {
            let dist: i32 = lx * 8 - x[i];
            if dist > 0 && dist < 560 {
                if v[i] > dist / 24 { v[i] = dist / 24; }
            }
        }
        i = i + 1;
    }
    i = 0;
    while i < 4 {
        x[i] = x[i] + v[i];
        if x[i] >= track { x[i] = x[i] - track; }
        host::display::state_set(8 + i * 2, x[i]);
        host::display::state_set(9 + i * 2, v[i]);
        i = i + 1;
    }
    host::display::clear(0x0c0c10);
    let ry: i32 = h / 2;
    host::display::fill_rect(0, ry - 18, w, 36, 0x242424);
    host::display::fill_rect(lx, ry - 24, 3, 48, 0xd0d0d0);
    host::display::fill_rect(lx - 10, ry - 70, 24, 40, 0x303030);
    if red {
        host::display::fill_rect(lx - 4, ry - 66, 12, 12, 0xdd3030);
    } else {
        host::display::fill_rect(lx - 4, ry - 46, 12, 12, 0x30dd40);
    }
    i = 0;
    while i < 4 {
        let c: i32 = if v[i] >= 12 { 0x60b0ff } else if v[i] >= 4 { 0xddbb30 } else { 0xdd4030 };
        host::display::fill_rect(x[i] / 8, ry - 6, 26, 12, c);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "QUEUE AT THE RED", 0x808080, 1);
    host::display::present();
}
